			            var instSe = app.lookup("cmbInstSe");  //기관구분
			            instSe.value = "";

			            var dtlInstSe = app.lookup("cmbDtlInstSe");  //상세기관구분
			            dtlInstSe.value = "";

			            var dsOgdpInst = app.lookup("dsOgdpInst");
			            dsOgdpInst.clearFilter();

			            if (crudType == "READ") {
			                util.DataMap.setValue(app, "dmListParam", "ESNTL_LINK_MNG_NO", rowData["ESNTL_LINK_MNG_NO"]);
			                doList();
			            } else {
			                dsOgdpInst.setFilter("CMMNS_CD_VALUE == ''");
			                doKey();  //key값가져오기 
			            }
			            
			            util.Control.redraw(app, "grpData");
			            
			            var cmbInstSe = app.lookup("cmbInstSe");
			            cmbInstSe.focus();
			            
